import {readFile} from 'node:fs/promises';
export async function directPage(t,api,{sdk,viewport={width:390,height:844},query=''}={}){
 const {chromium}=await import(process.env.PLAYWRIGHT_MODULE||'/Users/choi/.hermes/hermes-agent/node_modules/playwright/index.mjs');const browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_PATH||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});t.after(()=>browser.close());const page=await browser.newPage({viewport});page.setDefaultTimeout(10000);
 await page.route('**/*',async route=>{const u=new URL(route.request().url());if(u.href==='https://cdn.portone.io/v2/browser-sdk.js')return sdk?sdk(route):route.fulfill({contentType:'text/javascript',body:'window.calls=[];window.PortOne={requestPayment:async p=>{window.calls.push(p);return {code:"FAILURE_TYPE_STOPPED"};}}'});if(u.pathname.startsWith('/api/test/apply/')){const action=u.pathname.split('/').at(-1);const result=await api?.(action,route);if(result!==undefined)return result;if(action==='session'||action==='status')return route.fulfill({json:{status:'session-ready'}});return route.abort();}if(u.origin!=='https://cjy.app')return route.abort();if(u.pathname.startsWith('/component/'))return route.fulfill({contentType:'image/svg+xml',body:await readFile(new URL('../..'+u.pathname,import.meta.url))});const p=u.pathname.startsWith('/src/')?u.pathname:'/index.html';return route.fulfill({contentType:p.endsWith('.js')?'text/javascript':p.endsWith('.css')?'text/css':'text/html',body:await readFile(new URL('../..'+p,import.meta.url))});});
 await page.goto('https://cjy.app/apply'+query);await page.waitForFunction(()=>document.querySelector('[data-direct-checkout]'));
 const fill=async()=>{for(const [n,v] of Object.entries({customerName:'TEST',customerPhone:'01000000000',brief:'Synthetic request',testEmail:'test@example.invalid'}))await page.locator(`[name=${n}]`).fill(v);for(const n of ['termsConsent','privacyConsent'])await page.locator(`[name=${n}]`).check();};return {page,fill};
}
export const receipt='a0000000-0000-4000-8000-000000000001';
export const readyOrder={receipt,status:'checkout-ready',orderId:'owned',paymentId:'owned',storeId:'store-test',channelKey:'channel-test',orderName:'CJY Reels Standard',totalAmount:273900,currency:'KRW',payMethod:'CARD',customer:{fullName:'TEST',phoneNumber:'01000000000'},state:'pending_payment',environment:'test'};
